import {escapeHTML as e,recordFilters as f,chips} from './station-workspace.js';
import {dayLabel} from './daily-ui.js';
export let knowledgeCategory='all';
export const setCategory=v=>{knowledgeCategory=v;};
const date=v=>new Date(v).toLocaleString('zh-CN');
const labels={queued:'待整理',processing:'整理中',archived:'已归档',failed:'整理失败',withdrawn:'已撤回'};
const topic={habits:'生活习惯',likes:'喜好与互动',diet:'饮食照护',health:'健康观察',other:'其他观察'};
export function knowledgePanel(notes,owned){const rows=notes.filter(n=>knowledgeCategory==='all'||(knowledgeCategory==='health'?n.topic==='health':knowledgeCategory==='ongoing'?n.certainty==='ongoing':knowledgeCategory==='pending'?n.certainty==='pending':n.certainty==='observation'));return `<div class="section-heading"><h2>它的资料库</h2><button data-live="refresh" class="text-button">刷新</button></div>${chips('knowledge',[['all','全部'],['ongoing','长期'],['health','健康'],['short','短期'],['pending','待确认']],knowledgeCategory)}<p class="result-count">${rows.length} 条有效资料</p>${rows.map(n=>`<section class="online-card"><span class="status-pill">${topic[n.topic]||'观察'} · ${{ongoing:'长期观察',observation:'单次观察',pending:'待确认'}[n.certainty]||'观察'}</span><p>${e(n.quote)}</p><small>${e(n.station)} · ${date(n.recorded_at)}</small>${owned&&n.observation_id?`<button data-live="source-record" data-id="${e(n.observation_id)}" class="text-button">定位原始记录 →</button>`:''}</section>`).join('')||'<p class="online-note">还没有符合条件的有效资料。</p>'}`;}
// Daily records read as a timeline by the day things happened; the entry time and status stay visible.
const thumbs=r=>r.visuals?.length?`<div class="record-visuals">${r.visuals.map(v=>v.mime?.startsWith('video/')?`<video controls playsinline preload="metadata" src="${e(v.url)}"></video>`:`<img src="${e(v.url)}" alt="这条补充的照片">`).join('')}</div>`:'';
export function recordPanel(records,highlight=''){return `<section id="record-panel"><h2 class="spaced">补充记录</h2>${chips('record',[['all','全部'],['archived','已归档'],['processing','整理中'],['failed','失败'],['withdrawn','已撤回']],f.status)}<form id="record-search" class="record-search"><label>搜索原文<input name="q" type="search" value="${e(f.q)}" placeholder="输入关键词"></label><div class="date-filter"><label>开始日期<input name="from" type="date" value="${f.from}"></label><label>结束日期<input name="to" type="date" value="${f.to}"></label></div><label>时间顺序<select name="order"><option value="desc" ${f.order==='desc'?'selected':''}>最新在前</option><option value="asc" ${f.order==='asc'?'selected':''}>最早在前</option></select></label><button class="button secondary">查找记录</button>${f.id?'<button type="button" class="text-button" data-live="clear-record">返回全部记录</button>':''}</form><p class="online-note">显示符合条件的最近 100 条；可按日期缩小范围。</p>${records.map(r=>`<section class="online-card${r.id===highlight?' just-added':''}" id="record-${e(r.id)}"><div class="record-status"><strong>${e(dayLabel(r.observed_on)||'资料补充')}${r.id===highlight?' · 刚追加':''}</strong><span>${labels[r.status]||'处理中'}</span></div><p>${e(r.transcript||r.original_text||(r.media_id?'语音已保存，等待转写。':''))}</p>${thumbs(r)}<small>录入于 ${date(r.created_at)} · ${!r.original_text&&!r.transcript&&r.visuals?.length?'影像已存档':r.share_with_agent?'Agent 可引用':'仅本站可见'}${r.replaces_id?' · 更正过':''}</small><div class="online-actions">${r.status==='failed'?`<button data-live="retry" data-id="${e(r.id)}" class="button secondary">重新整理</button>`:''}${r.status!=='withdrawn'?`<button data-live="correct" data-id="${e(r.id)}" class="button secondary">更正</button><button data-live="withdraw" data-id="${e(r.id)}" class="text-button">撤回</button>`:''}</div></section>`).join('')||'<p class="online-note">没有找到符合条件的记录。</p>'}</section>`;}
export function gallery(media,pet,owned){const visuals=media?.length?media:pet?.profile.photoUrl?[{url:pet.profile.photoUrl,mime:'image/jpeg',caption:''}]:[];return `<section class="pet-media-gallery"><div class="gallery-rail">${visuals.length?visuals.map((v,i)=>`<figure>${v.mime?.startsWith('video/')?`<video controls playsinline preload="metadata" src="${e(v.url)}"></video>`:`<img class="station-pet-cover" src="${e(v.url)}" alt="${e(pet?.name)}的第 ${i+1} 张档案照片">`}<figcaption>${e(v.caption||'')}${v.createdAt?`<small>${date(v.createdAt)}${v.shared===false?' · 仅本站可见':''}</small>`:''}</figcaption></figure>`).join(''):'<p class="online-note">还没有上传照片或视频，拍下它今天的样子吧。</p>'}</div><div class="gallery-footer"><small>${visuals.length?`${visuals.length} 份影像 · 左右滑动查看`:'影像来自救助者实际上传'}</small>${owned?'<button class="button secondary" data-live="media">＋ 补充影像</button>':''}</div></section>`;}
